from taf.internal.core import Factory
from .file_transfer_factory_registry import FileGetterFactoryRegistry, FilePutterFactoryRegistry


class FileGetterFactory(Factory):
    def create(self, configuration, existing_arguments):
        factory_class = FileGetterFactoryRegistry.get_instance()[
            configuration["type"]]
        file_getter = factory_class().create(
            configuration=configuration,
            existing_arguments=existing_arguments)
        return file_getter


class FilePutterFactory(Factory):
    def create(self, configuration, existing_arguments):
        factory_class = FilePutterFactoryRegistry.get_instance()[
            configuration["type"]]
        file_putter = factory_class().create(
            configuration=configuration,
            existing_arguments=existing_arguments)
        return file_putter
